(()=>{const defaults={background:'#f9f9f9',gridColor:'#000000',gridOpacity:.1,gridLineOpacity:.1,gridSpacing:innerWidth<600?12:15,tabStroke:1.2,gradientPink:'#e9a2cf',gradientPeach:'#7f8df5',gradientCream:'#c7caf5',gradientSpeed:1,gradientNoise:0};function apply(config){for(const [key,value]of Object.entries(defaults))document.documentElement.style.setProperty('--site-'+key,config[key]??value);document.dispatchEvent(new Event('site-style-change'))}apply(defaults);fetch('site-config.json?v=garden-38',{cache:'no-store'}).then(r=>r.ok?r.json():defaults).then(apply).catch(()=>{})})();
